create extension if not exists pgcrypto;
do $$ begin create type media_status as enum ('draft','ready','scheduled','published','archived'); exception when duplicate_object then null; end $$;
do $$ begin create type media_kind as enum ('photo','video','reel','story'); exception when duplicate_object then null; end $$;
do $$ begin create type post_kind as enum ('post','reel','story'); exception when duplicate_object then null; end $$;
create table if not exists workspace_owners(user_id uuid primary key references auth.users(id) on delete cascade,display_name text,created_at timestamptz not null default now());
create table if not exists instagram_profiles(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,username text not null,display_name text,instagram_url text not null,profile_image_url text,category text,description text,followers_count bigint,verified boolean not null default false,is_pinned boolean not null default false,pin_order integer not null default 0,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,username));
create table if not exists folders(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null,description text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,name));
create table if not exists tags(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null,created_at timestamptz not null default now(),unique(owner_id,name));
create table if not exists media(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,instagram_profile_id uuid references instagram_profiles(id) on delete set null,folder_id uuid references folders(id) on delete set null,file_path text not null,thumbnail_path text,file_name text not null,mime_type text not null,file_size bigint,duration_seconds numeric,media_type media_kind not null,status media_status not null default 'draft',caption text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists media_tags(media_id uuid not null references media(id) on delete cascade,tag_id uuid not null references tags(id) on delete cascade,primary key(media_id,tag_id));
create table if not exists posts(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,instagram_profile_id uuid not null references instagram_profiles(id) on delete cascade,caption text,post_type post_kind not null default 'post',status media_status not null default 'draft',scheduled_at timestamptz,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists post_media(post_id uuid not null references posts(id) on delete cascade,media_id uuid not null references media(id) on delete cascade,sort_order integer not null default 0,primary key(post_id,media_id));
create table if not exists schedules(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,post_id uuid not null references posts(id) on delete cascade,instagram_profile_id uuid not null references instagram_profiles(id) on delete cascade,scheduled_at timestamptz not null,timezone text not null default 'Africa/Kigali',status text not null default 'scheduled',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists favorites(owner_id uuid not null references auth.users(id) on delete cascade,media_id uuid not null references media(id) on delete cascade,created_at timestamptz not null default now(),primary key(owner_id,media_id));
create table if not exists notifications(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,title text not null,body text,read_at timestamptz,created_at timestamptz not null default now());
create table if not exists activity_logs(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,action text not null,entity_type text,entity_id uuid,metadata jsonb,created_at timestamptz not null default now());
create index if not exists idx_ig_profiles_owner_pin on instagram_profiles(owner_id,is_pinned,pin_order);create index if not exists idx_media_owner_created on media(owner_id,created_at desc);create index if not exists idx_posts_owner_created on posts(owner_id,created_at desc);create index if not exists idx_schedules_owner_date on schedules(owner_id,scheduled_at);
alter table workspace_owners enable row level security;alter table instagram_profiles enable row level security;alter table folders enable row level security;alter table tags enable row level security;alter table media enable row level security;alter table media_tags enable row level security;alter table posts enable row level security;alter table post_media enable row level security;alter table schedules enable row level security;alter table favorites enable row level security;alter table notifications enable row level security;alter table activity_logs enable row level security;
create policy "owner workspace" on workspace_owners for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "owner profiles" on instagram_profiles for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);create policy "owner folders" on folders for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);create policy "owner tags" on tags for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);create policy "owner media" on media for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);create policy "owner posts" on posts for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);create policy "owner schedules" on schedules for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);create policy "owner favorites" on favorites for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);create policy "owner notifications" on notifications for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);create policy "owner logs" on activity_logs for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);